const char* MSG_ERROR = "Operation failed.";

// Stored in read-only memory
char* mutable_str = (char*)"DO NOT MODIFY";

// Attempted modification is Undefined Behavior
// mutable_str[0] = 'a'; // CRASH or failure

// Safe usage with array copy
char buffer[20];
strcpy(buffer, MSG_ERROR);

// Array initialized from literal is modifiable
char status[] = "Ready";
status[0] = 'R';

// Literal used in preprocessor
#define APP_VERSION "1.0.2"

// Compound literal (C99)
puts((const char[]){"Hello World"});
